package com.bookstore.service.impl; import com.bookstore.entity.*; import com.bookstore.exception.*; import com.bookstore.repository.*; import com.bookstore.service.OrderService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*; @Service public class OrderServiceImpl implements OrderService{private final OrderRepository orders;private final CustomerRepository customers;private final BookRepository books; public OrderServiceImpl(OrderRepository o,CustomerRepository c,BookRepository b){orders=o;customers=c;books=b;} @Transactional public Order create(Long customerId,List<Long> ids,List<Integer> qtys){if(ids==null||ids.isEmpty()||qtys==null||ids.size()!=qtys.size())throw new IllegalArgumentException("Select at least one book and provide matching quantities"); Order o=new Order();o.setCustomer(customers.findById(customerId).orElseThrow(()->new ResourceNotFoundException("Customer not found")));BigDecimal total=BigDecimal.ZERO;for(int x=0;x<ids.size();x++){int q=qtys.get(x)==null?0:qtys.get(x);if(q<=0)continue;Book b=books.findById(ids.get(x)).orElseThrow(()->new ResourceNotFoundException("Book not found"));if(b.getStockQuantity()<q)throw new InsufficientStockException("Insufficient stock for "+b.getTitle());b.setStockQuantity(b.getStockQuantity()-q);OrderItem i=new OrderItem();i.setBook(b);i.setQuantity(q);i.setUnitPrice(b.getPrice());i.setSubtotal(b.getPrice().multiply(BigDecimal.valueOf(q)));o.addItem(i);total=total.add(i.getSubtotal());}if(o.getItems().isEmpty())throw new IllegalArgumentException("At least one quantity must be greater than zero");o.setTotal(total);return orders.save(o);} public List<Order> findAll(){return orders.findAll();} public Order findById(Long id){return orders.findDetailedById(id).orElseThrow(()->new ResourceNotFoundException("Order not found: "+id));} public List<Order> findByCustomer(Long id){return orders.findByCustomerIdOrderByOrderDateDesc(id);} @Transactional public Order updateStatus(Long id,OrderStatus s){Order o=findById(id);o.setStatus(s);return orders.save(o);}public long count(){return orders.count();}public BigDecimal totalSales(){return orders.totalSales();}}